#include "dual_pending.hpp"
int main(int argc,char**argv){try{
 if(argc!=4)throw std::runtime_error("SHADERS INPUT OUT");std::filesystem::path input=argv[2],out=argv[3];
 std::vector<std::vector<float>> masks,verts;for(int i:{1,3,5}){auto d=input/std::to_string(i);masks.push_back(read((d/"atlas.f32").c_str()));verts.push_back(read((d/"vertices.f32").c_str()));if(masks.back().size()!=3185||verts.back().size()!=24)throw std::runtime_error("input dimensions");for(float x:masks.back())if(x<0||x>1)throw std::runtime_error("mask range");for(size_t k=0;k<verts.back().size();k+=4)if(std::abs(verts.back()[k])>4||std::abs(verts.back()[k+1])>4||verts.back()[k+2]<0||verts.back()[k+2]>1||verts.back()[k+3]<0||verts.back()[k+3]>1)throw std::runtime_error("vertex bounds");}
 const auto savedMasks=masks,savedVerts=verts;if(!std::filesystem::create_directory(out))throw std::runtime_error("existing output");std::ofstream events(out/"events.jsonl");unsigned done=0;
 {
 auto av=std::make_unique<TextLab>(argv[1]);auto ae=std::make_unique<Engine>(*av);TextLab bv(argv[1]);Engine be(bv);if(!av->validation||!bv.validation||av->device==bv.device)throw std::runtime_error("separate validated device handles");ae->freeImage(av->coverage);be.freeImage(bv.coverage);
 auto& ap=ae->page(0);auto& au=ae->upload(ap,masks[0]);ae->wait(au);if(!ae->publish(ap))throw std::runtime_error("A publish");bool aPaused=false;auto drawA=[&](const std::vector<float>& v,uint64_t gate)->SubmissionResources&{if(aPaused)throw std::runtime_error("A paused");return ae->drawPublished(v,gate);};auto& ad=drawA(verts[0],1);aPaused=true;size_t beforePause=ae->submissions.size();bool pauseRejected=false;try{drawA(verts[0],0);}catch(const std::runtime_error& e){if(std::string(e.what())!="A paused")throw;pauseRejected=true;}if(!pauseRejected||ae->submissions.size()!=beforePause)throw std::runtime_error("pause guard side effects");
 auto pending=[&](){uint64_t n=99;VK(vkGetSemaphoreCounterValue(av->device,ae->gate,&n));if(n!=0||vkGetFenceStatus(av->device,ad.fence)!=VK_NOT_READY)throw std::runtime_error("A not gated");};
 auto event=[&](const char*phase,bool pend){events<<"{\"phase\":\""<<phase<<"\",\"A_pending\":"<<(pend?"true":"false")<<",\"B_completed\":"<<done<<",\"B_generation\":"<<be.publishedGeneration()<<",\"B_live_pages\":"<<be.livePages()<<"}\n";};pending();event("A_gated",true);
 if(be.publish(ap))throw std::runtime_error("foreign publication allowed");bool rejected=false;try{be.draw(ap,verts[0]);}catch(const std::runtime_error&e){if(std::string(e.what())!="foreign device page")throw;rejected=true;}if(!rejected)throw std::runtime_error("foreign draw allowed");
 auto& bp=be.page(0);auto& bu=be.upload(bp,masks[0]);be.wait(bu);if(!be.publish(bp))throw std::runtime_error("B publish");auto& bd=be.drawPublished(verts[0]);be.wait(bd);++done;dump(bd,out/"B-initial");pending();event("B_initial",true);
 auto& cp=be.page(1);auto& cu=be.upload(cp,masks[1]);be.wait(cu);be.cancel(cp);if(be.publish(cp))throw std::runtime_error("cancel publication allowed");auto& wrong=be.draw(cp,verts[1]);be.wait(wrong);++done;dump(wrong,out/"B-wrong-route");be.retire(cp);pending();event("B_canceled",true);
 auto& np=be.page(2);auto& nu=be.upload(np,masks[2]);be.wait(nu);if(!be.publish(np)||be.publish(bp))throw std::runtime_error("generation guard");auto& nd=be.drawPublished(verts[2]);be.wait(nd);++done;dump(nd,out/"B-new");be.retire(bp);pending();event("B_new",true);
 ae->signal(1);ae->wait(ad);dump(ad,out/"A-released");ae.reset();av.reset();if(validationErrors)throw std::runtime_error("A destruction validation");event("A_destroyed",false);
 auto& continued=be.drawPublished(verts[2]);be.wait(continued);++done;dump(continued,out/"B-after-A-destroyed");event("B_continued",false);
 av=std::make_unique<TextLab>(argv[1]);ae=std::make_unique<Engine>(*av);if(!av->validation||av->device==bv.device)throw std::runtime_error("rebuilt device identity");ae->freeImage(av->coverage);auto& rp=ae->page(0);auto& ru=ae->upload(rp,masks[1]);ae->wait(ru);if(!ae->publish(rp))throw std::runtime_error("rebuilt publish");auto& rd=ae->drawPublished(verts[1]);ae->wait(rd);dump(rd,out/"A-rebuilt");event("A_rebuilt",false);
 auto& last=be.drawPublished(verts[2]);be.wait(last);++done;dump(last,out/"B-after-A-rebuilt");event("B_final",false);ae.reset();av.reset();if(masks!=savedMasks||verts!=savedVerts)throw std::runtime_error("CPU input mutated");
 }
 if(validationErrors)throw std::runtime_error("final validation");events<<"{\"phase\":\"all_destroyed\",\"B_completed\":"<<done<<"}\n";std::cout<<"CACHE_DUAL_MRT_PASS validation_enabled=1 logical_devices_created=3\n";return 0;
 }catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
